#define SWITCH_EMACCNTP_UESLESS_EMAC3_CNTP_AFULL_STOP_EN_V  0x1
#define SWITCH_EMACCNTP_UESLESS_EMAC3_CNTP_AFULL_STOP_EN_S  3
/* SWITCH_EMACCNTP_UESLESS_EMAC2_CNTP_AFULL_STOP_EN : RO ;bitpos:[2] ;default: 1'b1 ; */
/*description: Useless, don't care.*/
#define SWITCH_EMACCNTP_UESLESS_EMAC2_CNTP_AFULL_STOP_EN    (BIT(2))
#define SWITCH_EMACCNTP_UESLESS_EMAC2_CNTP_AFULL_STOP_EN_M  (BIT(2))
#define SWITCH_EMACCNTP_UESLESS_EMAC2_CNTP_AFULL_STOP_EN_V  0x1
#define SWITCH_EMACCNTP_UESLESS_EMAC2_CNTP_AFULL_STOP_EN_S  2
/* SWITCH_EMACCNTP_UESLESS_EMAC1_CNTP_AFULL_STOP_EN : RO ;bitpos:[1] ;default: 1'b1 ; */
/*description: Useless, don't care.*/
#define SWITCH_EMACCNTP_UESLESS_EMAC1_CNTP_AFULL_STOP_EN    (BIT(1))
#define SWITCH_EMACCNTP_UESLESS_EMAC1_CNTP_AFULL_STOP_EN_M  (BIT(1))
