#define SWITCH_EMACCNTP_CTRL_REG          (DR_REG_SWITCH_EMAC_CNTP_MEM_BASE + 0x10)
/* SWITCH_EMACCNTP_EMAC_RAM1_CLR_DONE : RO ;bitpos:[9] ;default: 1'h1 ; */
/*description: 1'b1 : RAM1 clear done; 1'b0 : RAM1 is being cleaning.*/
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_DONE    (BIT(9))
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_DONE_M  (BIT(9))
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_DONE_V  0x1
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_DONE_S  9
/* SWITCH_EMACCNTP_EMAC_RAM0_CLR_DONE : RO ;bitpos:[8] ;default: 1'h1 ; */
/*description: 1'b1 : RAM0 clear done; 1'b0 : RAM0 is being cleaning.*/
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_DONE    (BIT(8))
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_DONE_M  (BIT(8))
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_DONE_V  0x1
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_DONE_S  8
/* SWITCH_EMACCNTP_EMAC_RAM1_CLR_TYPE : R/W/SC ;bitpos:[3:2] ;default: 2'h0 ; */
/*description: 2'b11 : RAM1 total clear; 2'b10 : RAM1 range id clear; 2'b01 : RAM1 single id cl
ear; 2'b00 : RAM1 dont need clear.*/
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_TYPE    0x00000003
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_TYPE_M  ((SWITCH_EMACCNTP_EMAC_RAM1_CLR_TYPE_V)<<(SWITCH_EMACCNTP_EMAC_RAM1_CLR_TYPE_S))
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_TYPE_V  0x3
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_TYPE_S  2
/* SWITCH_EMACCNTP_EMAC_RAM0_CLR_TYPE : R/W/SC ;bitpos:[1:0] ;default: 2'h0 ; */
/*description: 2'b11 : RAM0 total clear; 2'b10 : RAM0 range id clear; 2'b01 : RAM0 single id cl
ear; 2'b00 : RAM0 dont need clear.*/
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_TYPE    0x00000003
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_TYPE_M  ((SWITCH_EMACCNTP_EMAC_RAM0_CLR_TYPE_V)<<(SWITCH_EMACCNTP_EMAC_RAM0_CLR_TYPE_S))
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_TYPE_V  0x3
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_TYPE_S  0

#define SWITCH_EMACCNTP_RAM0_RANGE_CLEAR_REG          (DR_REG_SWITCH_EMAC_CNTP_MEM_BASE + 0x14)
/* SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_RANGE : R/W ;bitpos:[31:16] ;default: 16'h0 ; */
/*description: 0base, When ram0_clr_type=2'b10 cntp clear range is (ram0_clr_id_base ~ ram0_clr
_id_base + ram0_clr_id_range).*/
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_RANGE    0x0000FFFF
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_RANGE_M  ((SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_RANGE_V)<<(SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_RANGE_S))
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_RANGE_V  0xFFFF
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_RANGE_S  16
/* SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_BASE : R/W ;bitpos:[15:0] ;default: 16'h0 ; */
/*description: when ram0_clr_type = 2'b10 or 2'b01 cntp clear start from ram0_clr_id_base; When
 ram0_clr_type = 2'b11 clear starts from 0.*/
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_BASE    0x0000FFFF
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_BASE_M  ((SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_BASE_V)<<(SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_BASE_S))
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_BASE_V  0xFFFF
#define SWITCH_EMACCNTP_EMAC_RAM0_CLR_ID_BASE_S  0

#define SWITCH_EMACCNTP_RAM1_RANGE_CLEAR_REG          (DR_REG_SWITCH_EMAC_CNTP_MEM_BASE + 0x18)
/* SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_RANGE : R/W ;bitpos:[31:16] ;default: 16'h0 ; */
/*description: 0base, When ram1_clr_type =2'b10 clr range is (ram1_clr_id_base ~ ram1_clr_id_ba
se + ram1_clr_id_range).*/
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_RANGE    0x0000FFFF
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_RANGE_M  ((SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_RANGE_V)<<(SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_RANGE_S))
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_RANGE_V  0xFFFF
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_RANGE_S  16
/* SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_BASE : R/W ;bitpos:[15:0] ;default: 16'h0 ; */
/*description: when ram1_clr_type = 2'b10 or 2'b01 cntp clear start from ram1_clr_id_base; When
 ram1_clr_type = 2'b11 cntp clear starts from 0.*/
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_BASE    0x0000FFFF
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_BASE_M  ((SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_BASE_V)<<(SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_BASE_S))
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_BASE_V  0xFFFF
#define SWITCH_EMACCNTP_EMAC_RAM1_CLR_ID_BASE_S  0

#define SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_31TO0_REG          (DR_REG_SWITCH_EMAC_CNTP_MEM_BASE + 0x1C)
/* SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_31TO0 : R/W ;bitpos:[31:0] ;default: 32'b0 ; */
/*description: low 32 bit of the emac1 receive total packet number,this is incremented for each
 good or bad frame.*/
#define SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_31TO0    0xFFFFFFFF
#define SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_31TO0_M  ((SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_31TO0_V)<<(SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_31TO0_S))
#define SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_31TO0_V  0xFFFFFFFF
#define SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_31TO0_S  0

#define SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_63TO32_REG          (DR_REG_SWITCH_EMAC_CNTP_MEM_BASE + 0x20)
/* SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_63TO32 : R/W ;bitpos:[9:0] ;default: 10'b0 ; */
/*description: high 32 bit of the emac1 receive total packet number,this is incremented for eac
h good or bad frame.*/
#define SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_63TO32    0x000003FF
#define SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_63TO32_M  ((SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_63TO32_V)<<(SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_63TO32_S))
#define SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_63TO32_V  0x3FF
#define SWITCH_EMACCNTP_EMAC1_RX_PACKET_NUM_63TO32_S  0

#define SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_31TO0_REG          (DR_REG_SWITCH_EMAC_CNTP_MEM_BASE + 0x24)
/* SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_31TO0 : R/W ;bitpos:[31:0] ;default: 32'b0 ; */
/*description: low 32 bit of the emac1 receive pause frame number,and is good frame.*/
#define SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_31TO0    0xFFFFFFFF
#define SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_31TO0_M  ((SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_31TO0_V)<<(SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_31TO0_S))
#define SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_31TO0_V  0xFFFFFFFF
#define SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_31TO0_S  0

#define SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_63TO32_REG          (DR_REG_SWITCH_EMAC_CNTP_MEM_BASE + 0x28)
/* SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_63TO32 : R/W ;bitpos:[9:0] ;default: 10'b0 ; */
/*description: high 32 bit of the emac1 receive pause frame number,and is good frame.*/
#define SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_63TO32    0x000003FF
#define SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_63TO32_M  ((SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_63TO32_V)<<(SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_63TO32_S))
#define SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_63TO32_V  0x3FF
#define SWITCH_EMACCNTP_EMAC1_RX_PAUSE_PACKET_NUM_63TO32_S  0

#define SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_31TO0_REG          (DR_REG_SWITCH_EMAC_CNTP_MEM_BASE + 0x2C)
/* SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_31TO0 : R/W ;bitpos:[31:0] ;default: 32'b0 ; */
/*description: low 32 bit of the emac1 receive undersize frame number, this is incremented each
 time a frame is received which is less than 64 Byte(about phy interface), and i
nclude good fcs.*/
#define SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_31TO0    0xFFFFFFFF
#define SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_31TO0_M  ((SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_31TO0_V)<<(SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_31TO0_S))
#define SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_31TO0_V  0xFFFFFFFF
#define SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_31TO0_S  0

#define SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_63TO32_REG          (DR_REG_SWITCH_EMAC_CNTP_MEM_BASE + 0x30)
/* SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_63TO32 : R/W ;bitpos:[9:0] ;default: 10'b0 ; */
/*description: high 32 bit of the emac1 receive undersize frame number, this is incremented eac
h time a frame is received which is less than 64 Byte(about phy interface), and
include good fcs.*/
#define SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_63TO32    0x000003FF
#define SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_63TO32_M  ((SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_63TO32_V)<<(SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_63TO32_S))
#define SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_63TO32_V  0x3FF
#define SWITCH_EMACCNTP_EMAC1_RX_UNDERSIZE_PACKET_NUM_63TO32_S  0

#define SWITCH_EMACCNTP_EMAC1_RX_64_PACKET_NUM_31TO0_REG          (DR_REG_SWITCH_EMAC_CNTP_MEM_BASE + 0x34)
/* SWITCH_EMACCNTP_EMAC1_RX_64_PACKET_NUM_31TO0 : R/W ;bitpos:[31:0] ;default: 32'b0 ; */
/*description: low 32 bit of the emac1 receive 64 byte frame number,this bit is increment for e
ach good or bad frame, and include 4 byte fcs.*/
#define SWITCH_EMACCNTP_EMAC1_RX_64_PACKET_NUM_31TO0    0xFFFFFFFF
#define SWITCH_EMACCNTP_EMAC1_RX_64_PACKET_NUM_31TO0_M  ((SWITCH_EMACCNTP_EMAC1_RX_64_PACKET_NUM_31TO0_V)<<(SWITCH_EMACCNTP_EMAC1_RX_64_PACKET_NUM_31TO0_S))
#define SWITCH_EMACCNTP_EMAC1_RX_64_PACKET_NUM_31TO0_V  0xFFFFFFFF
#define SWITCH_EMACCNTP_EMAC1_RX_64_PACKET_NUM_31TO0_S  0

#define SWITCH_EMACCNTP_EMAC1_RX_64_PACKET_NUM_63TO32_REG          (DR_REG_SWITCH_EMAC_CNTP_MEM_BASE + 0x38)
/* SWITCH_EMACCNTP_EMAC1_RX_64_PACKET_NUM_63TO32 : R/W ;bitpos:[9:0] ;default: 10'b0 ; */
/*description: high 32 bit of the emac1 receive 64 byte frame number,this bit is increment for
each good or bad frame, and include 4 byte fcs.*/
